import styled from "styled-components";

export const PropertySiteContainer= styled.div`
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-top: 2rem;
    position: relative;
    

 
    
    
`

export const CardImage= styled.div`
    width:100%;
    height: 50%;
    border-radius:2px;
    object-fit: cover;
  
    img{
        width: 100%;
        height: 100%;
        object-fit: cover;
    }
`
export const priceContainer= styled.div`
        width: 4rem;
        height:2rem;
        border-radius:20%;
`
